/bin/bash -lc "python3 - <<'PY'
import pathlib
import subprocess
import tempfile
source = r'''
#include \"service.hpp\"
#include <cassert>
int main() {
    std::string input;
    for (int byte = 0; byte < 256; ++byte) input += static_cast<char>(byte);
    const std::string encoded = csvField(input);
    assert(encoded.size() == input.size() + 3);
    assert(encoded.front() == '\"' && encoded.back() == '\"');
    std::size_t pos = 1;
    for (char byte : input) {
        assert(encoded[pos++] == byte);
        if (byte == '\"') assert(encoded[pos++] == '\"');
    }
    assert(pos == encoded.size() - 1);
    assert(csvField(\"\\\"\\\"\") == std::string(6, '\"'));
}
'''
with tempfile.TemporaryDirectory(prefix='csvfield-check-') as temporary:
    binary = pathlib.Path(temporary) / 'check'
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-I', '.', '-x', 'c++', '-o', str(binary), '-'], input=source, text=True, check=True)
    subprocess.run([str(binary)], check=True)
print('All-byte preservation and consecutive-quote checks passed.')
PY"

